div.script:
(function(){
  var txt=document.getElementById('qo-text'), go=document.getElementById('qo-review'),
      out=document.getElementById('qo-out'), csrf=document.getElementById('qo-csrf').value;
  var lines=[];
  function el(tag,cls,text){var e=document.createElement(tag); if(cls){e.className=cls;} if(text!==undefined){e.textContent=text;} return e;}
  function money(n){return '$'+Number(n).toFixed(2);}
  function norm(o,n){
    n=parseInt(n,10); if(!(n>0)){n=1;}
    var r=o&&o.rule?o.rule:null; if(!r){return n;}
    return Math.max(r[0],Math.floor((n+Math.floor(r[1]/2))/r[1])*r[1]);
  }
  function fixQty(l){
    var o=current(l); if(!o){return;}
    var n=norm(o,l.qty);
    if(n!==l.qty){l.qty=n; l.adj=true;}
  }
  function post(url,data){
    var fd=new FormData(); fd.append('csrf_token',csrf);
    Object.keys(data).forEach(function(k){fd.append(k,data[k]);});
    return fetch(url,{method:'POST',body:fd,credentials:'same-origin'}).then(function(r){return r.json();});
  }
  function forget(l){
    post('/pedido-rapido/olvidar',{alias:l.text}).then(function(){
      return post('/pedido-rapido/revisar',{texto:l.raw});
    }).then(function(d){
      var n=d.lines&&d.lines[0]; if(!n){return;}
      n.remembered=false; n.skip=false; n.qty=l.qty; n.adj=false;
      n.pick=(n.status==='ok')?0:null;
      lines[lines.indexOf(l)]=n; render();
    });
  }
  function current(l){
    if(l.skip||l.pick===null){return null;}
    var o=l.options[l.pick];
    return (o&&!o.variants)?o:null;
  }
  function anyAdded(l){return l.options.some(function(o){return o.added;});}
  function addOne(l,o,btn){
    var n=norm(o,o.q||o.rule[0]);
    if(window.dkFly){window.dkFly(btn);}
    btn.disabled=true; btn.textContent='Agregando…';
    post('/pedido-rapido/agregar',{items:JSON.stringify([{template_id:o.template_id,qty:n,name:o.name,alias:l.text,learn:(l.status==='suggest')}])})
      .then(function(d){
        if(d.skipped&&d.skipped.length){btn.disabled=false; btn.textContent='Agregar'; alert('No se pudo agregar: '+d.skipped.join(', ')); return;}
        o.added=(o.added||0)+n; render();
      })
      .catch(function(){btn.disabled=false; btn.textContent='Agregar'; alert('No se pudo agregar. Intenta de nuevo.');});
  }
  /* Opciones como catálogo: foto, nombre, precio, cantidad y botón Agregar en cada tarjeta. */
  function catalog(l){
    var box=el('div','qo-sbox');
    var head=el('div','qo-shead');
    head.appendChild(el('span','qo-stag',l.status==='suggest'?'SUGERENCIAS':'OPCIONES'));
    head.appendChild(el('span','qo-stxt','Aún no están en tu pedido'));
    box.appendChild(head);
    var grid=el('div','qo-sugs');
    box.appendChild(grid);
    l.options.forEach(function(o){
      if(!o.q){o.q=norm(o,l.qty);}
      var card=el('div','qo-sug'+(o.added?' on':''));
      card.appendChild(el('span',o.added?'qo-state yes':'qo-state no',o.added?'✓ En tu pedido':'No agregado'));
      var im=el('img'); im.src=o.image; im.alt=''; im.loading='lazy'; card.appendChild(im);
      var tx=el('div','qo-sug-t'); tx.appendChild(el('b',null,o.name)); tx.appendChild(el('small',null,money(o.price)+' c/u'));
      if(o.added){tx.appendChild(el('span','qo-adj',o.added+' agregadas'));}
      card.appendChild(tx);
      if(o.variants){
        var a=el('a','qo-link','Tiene variantes: ábrelo'); a.href=o.url; card.appendChild(a);
      } else {
        var ctl=el('div','qo-sug-c');
        var mi=el('button','qo-sug-s','−'); mi.type='button'; mi.setAttribute('aria-label','Menos');
        var inp=el('input','qo-sug-q'); inp.type='text'; inp.setAttribute('inputmode','numeric'); inp.value=o.q; inp.setAttribute('aria-label','Cantidad');
        var pl=el('button','qo-sug-s','+'); pl.type='button'; pl.setAttribute('aria-label','Más');
        var r=o.rule;
        mi.addEventListener('click',function(){ if(o.q-r[1]<r[0]){ if(window.dkToast){window.dkToast(window.dkRuleMsg({min:r[0],step:r[1]}));} return; } o.q=o.q-r[1]; inp.value=o.q; });
        pl.addEventListener('click',function(){o.q=o.q+r[1]; inp.value=o.q;});
        inp.addEventListener('focus',function(){inp.select();});
        inp.addEventListener('change',function(){var t=parseInt(inp.value,10); o.q=norm(o,inp.value); inp.value=o.q; if(t!==o.q&&window.dkToast){window.dkToast(window.dkRuleMsg({min:r[0],step:r[1]})+' Quedó en '+o.q+'.');}});
        var ab=el('button','qo-sug-add',o.added?'Agregar más':'Agregar'); ab.type='button';
        ab.addEventListener('click',function(){o.q=norm(o,inp.value); addOne(l,o,ab);});
        ctl.appendChild(mi); ctl.appendChild(inp); ctl.appendChild(pl); ctl.appendChild(ab);
        card.appendChild(ctl);
      }
      grid.appendChild(card);
    });
    return box;
  }
  function render(){
    out.textContent='';
    if(!lines.length){return;}
    var list=el('div','qo-list'), total=0, ready=0, pending=0, missing=0, added=0;
    lines.forEach(function(l){
      var row=el('div','qo-row'+(l.skip?' skip':'')+((l.status==='suggest'||l.status==='choose')?' sug':''));
      var left=el('div','qo-left');
      left.appendChild(el('div','qo-raw',l.raw));
      if(l.status==='choose'&&l.total>l.options.length){left.appendChild(el('div','qo-note',l.options.length+' de '+l.total));}
      row.appendChild(left);
      var mid=el('div','qo-mid');
      if(l.status==='missing'){
        mid.appendChild(el('span','qo-chip bad','No encontrado'));
        if(!l.skip){missing++;}
      } else {
        if(l.status==='suggest'||(l.status==='choose'&&l.options.length>1)){
          mid.appendChild(catalog(l));
        }
        var o=(l.pick===null)?null:l.options[l.pick];
        if(o&&!l.skip){fixQty(l);}
        if(o){
          var prod=el('div','qo-prod'), img=el('img'); img.src=o.image; img.alt=''; prod.appendChild(img);
          var info=el('div'); info.appendChild(el('div','qo-pname',o.name));
          var pr=el('div','qo-price');
          if(o.variants){
            var a=el('a',null,'Tiene variantes: ábrelo en la tienda'); a.href=o.url; pr.appendChild(a);
          } else { pr.textContent=money(o.price)+' c/u'; }
          info.appendChild(pr);
          if(l.remembered){
            var nr=el('button','qo-link','No es este'); nr.type='button';
            nr.addEventListener('click',function(){forget(l);});
            info.appendChild(nr);
          }
          if(l.adj){info.appendChild(el('span','qo-adj','cantidad ajustada'));}
          prod.appendChild(info); mid.appendChild(prod);
        }
        if(!l.skip){
          var cur=current(l);
          if(cur){ready++; total+=cur.price*l.qty;}
          else if(l.status==='suggest'||l.status==='choose'){ if(anyAdded(l)){added++;} else {pending++;} }
          else {pending++;}
        }
      }
      row.appendChild(mid);
      var qty=el('input','qo-qty'); qty.type='text'; qty.setAttribute('inputmode','numeric'); qty.value=l.qty;
      qty.setAttribute('aria-label','Cantidad');
      qty.addEventListener('focus',function(){qty.select();});
      qty.addEventListener('change',function(){var v=parseInt(qty.value,10); l.qty=(v>0?v:1); l.adj=false; render();});
      row.appendChild(qty);
      var x=el('button','qo-x',l.skip?'↺':'×'); x.type='button';
      x.setAttribute('aria-label',l.skip?'Volver a incluir':'Quitar línea');
      x.addEventListener('click',function(){l.skip=!l.skip; render();});
      row.appendChild(x);
      list.appendChild(row);
    });
    out.appendChild(list);
    var sum=el('div','qo-sum'), st=el('div','qo-sumtxt');
    st.appendChild(el('div',null,(ready+added)+' listos'+(pending?' · '+pending+' por elegir':'')+(missing?' · '+missing+' sin resultado':'')));
    st.appendChild(el('div','qo-total',money(total)));
    sum.appendChild(st);
    var add=el('button','qo-btn',(ready===0&&added)?'Ir al carrito':'Agregar al carrito'); add.type='button'; add.disabled=(ready===0&&!added);
    add.addEventListener('click',function(){ if(ready===0&&added){window.location.href='/shop/cart';} else {addAll(add);} });
    sum.appendChild(add);
    out.appendChild(sum);
  }
  function addAll(btn){
    var items=[];
    lines.forEach(function(l){var o=current(l); if(o){items.push({template_id:o.template_id,qty:l.qty,name:o.name,alias:l.text,learn:(l.status==='choose'||l.status==='suggest')});}});
    if(!items.length){return;}
    btn.disabled=true; btn.textContent='Agregando…';
    var fd=new FormData(); fd.append('csrf_token',csrf); fd.append('items',JSON.stringify(items));
    fetch('/pedido-rapido/agregar',{method:'POST',body:fd,credentials:'same-origin'})
      .then(function(r){return r.json();})
      .then(function(d){
        if(d.skipped&&d.skipped.length){alert('No se pudieron agregar: '+d.skipped.join(', '));}
        window.location.href='/shop/cart';
      })
      .catch(function(){btn.disabled=false; btn.textContent='Agregar al carrito'; alert('No se pudo agregar al carrito. Intenta de nuevo.');});
  }
  // Al pegar una lista se revisa sola (un toque menos).
  txt.addEventListener('paste',function(){setTimeout(function(){ if(txt.value.trim()){go.click();} },60);});
  /* --- modo foto --- */
  var tabT=document.getElementById('qo-tab-t'), tabP=document.getElementById('qo-tab-p'),
      photo=document.getElementById('qo-photo'), files=document.getElementById('qo-files'),
      readBtn=document.getElementById('qo-read'), thumbs=document.getElementById('qo-thumbs'),
      pmsg=document.getElementById('qo-photo-msg');
  function showTab(isPhoto){
    if(!tabT){return;}
    tabT.classList.toggle('on',!isPhoto); tabP.classList.toggle('on',isPhoto);
    tabT.setAttribute('aria-selected',String(!isPhoto)); tabP.setAttribute('aria-selected',String(isPhoto));
    photo.hidden=!isPhoto; txt.hidden=isPhoto; go.hidden=isPhoto;
  }
  if(tabT){
    tabT.addEventListener('click',function(){showTab(false);});
    tabP.addEventListener('click',function(){showTab(true);});
    files.addEventListener('change',function(){
      thumbs.textContent='';
      var n=Math.min(files.files.length,5);
      for(var i=0;i<n;i++){
        var im=el('img'); im.alt='Foto '+(i+1); im.src=URL.createObjectURL(files.files[i]); thumbs.appendChild(im);
      }
      pmsg.textContent=files.files.length>5?'Se leerán las primeras 5 fotos.':'';
      readBtn.disabled=(n===0);
    });
    readBtn.addEventListener('click',function(){
      var fd=new FormData(); fd.append('csrf_token',csrf);
      for(var i=0;i<Math.min(files.files.length,5);i++){fd.append('fotos',files.files[i]);}
      readBtn.disabled=true; readBtn.textContent='Leyendo…'; pmsg.textContent='';
      fetch('/pedido-rapido/foto',{method:'POST',body:fd,credentials:'same-origin'})
        .then(function(r){return r.json().then(function(d){return {ok:r.ok,d:d};});})
        .then(function(x){
          readBtn.disabled=false; readBtn.textContent='Leer lista';
          if(!x.ok||!x.d.texto){pmsg.textContent=(x.d&&x.d.error)||'No pudimos leer la lista. Intenta con otra foto.'; return;}
          txt.value=x.d.texto; showTab(false); go.click();
        })
        .catch(function(){readBtn.disabled=false; readBtn.textContent='Leer lista'; pmsg.textContent='No se pudo enviar la foto. Intenta de nuevo.';});
    });
  }
  go.addEventListener('click',function(){
    var t=txt.value.trim();
    if(!t){txt.focus(); return;}
    go.disabled=true; go.textContent='Revisando…';
    var fd=new FormData(); fd.append('csrf_token',csrf); fd.append('texto',t);
    fetch('/pedido-rapido/revisar',{method:'POST',body:fd,credentials:'same-origin'})
      .then(function(r){return r.json();})
      .then(function(d){
        lines=d.lines.map(function(l){l.skip=false; l.adj=false; l.pick=(l.status==='ok')?0:null; return l;});
        go.disabled=false; go.textContent='Revisar de nuevo';
        render();
        if(d.truncated){alert('Solo se revisaron las primeras 200 líneas.');}
      })
      .catch(function(){go.disabled=false; go.textContent='Revisar pedido'; alert('No se pudo revisar la lista. Intenta de nuevo.');});
  });
})();
